cat > /tmp/claude-0/-home-user-kahvi-work-slots-slot-2/cf3e6981-64ad-4f72-a0ef-6142cdcc90f3/scratchpad/new.rs <<'EOF'
    let _ = new_target;
    // 1. Let obj be the *this* value.
    // 2. Let taRecord be ? ValidateTypedArray(obj, ~seq-cst~).
    let rec = typed_array::validate_typed_array(agent, this)?;
    let obj = rec.object;
    // 3. Let length be TypedArrayLength(taRecord).
    let length = typed_array::length(agent, rec);
    // 4. If IsCallable(callback) is false, throw a TypeError exception.
    let callback = args.get_or_undefined(0);
    if !ops::is_callable(agent, callback) {
        return Err(agent.throw_type_error("TypedArray.prototype.reduceRight callback is not a function"));
    }
    let initial_value = args.get(1).copied();
    // 5. If length = 0 and initialValue is not present, throw a TypeError exception.
    if length == 0 && initial_value.is_none() {
        return Err(agent.throw_type_error("Reduce of empty array with no initial value"));
    }
    // 6. Let k be length - 1.
    let mut k = length as f64 - 1.0;
    // 7. Let accumulator be undefined.
    let mut accumulator = Value::Undefined;
    // The callback may collect garbage: obj, callback and the accumulator stay rooted.
    agent.with_roots(&[Value::Object(obj), callback], |agent| {
        // 8. If initialValue is present, then
        if let Some(initial_value) = initial_value {
            // a. Set accumulator to initialValue.
            accumulator = initial_value;
        } else {
            // 9. Else,
            // a. Set accumulator to TypedArrayGetElement(obj, 𝔽(k)).
            accumulator = typed_array::typed_array_get_element(agent, obj, k);
            // b. Set k to k - 1.
            k -= 1.0;
        }
        // 10. Repeat, while k ≥ 0,
        while k >= 0.0 {
            // a. Let kValue be TypedArrayGetElement(obj, 𝔽(k)).
            let k_value = typed_array::typed_array_get_element(agent, obj, k);
            // b. Set accumulator to ? Call(callback, undefined, « accumulator, kValue, 𝔽(k), obj »).
            let mark = agent.push_root(accumulator);
            agent.push_root(k_value);
            let result = ops::call_rooted(
                agent,
                callback,
                Value::Undefined,
                &[accumulator, k_value, Value::Number(k), Value::Object(obj)],
            );
            agent.pop_roots(mark);
            accumulator = result?;
            // c. Set k to k - 1.
            k -= 1.0;
        }
        // 11. Return accumulator.
        Ok(accumulator)
    })
EOF
